#!/usr/bin/env node
/*
 * check-action-versions.mjs — quarterly GitHub Actions freshness check (zero deps).
 *
 * Dependabot's minimum cadence is monthly; spab wants quarterly and has ZERO package
 * dependencies, so the only thing that drifts is the pinned action versions in
 * .github/workflows/*. This script (run by deps-quarterly.yml on a quarterly cron)
 * parses those pins, asks the GitHub API for each action's latest release tag, and —
 * only if something is behind — opens or updates a single tracking issue.
 *
 * Uses global fetch (Node 20+) and GITHUB_TOKEN. No npm dependencies.
 *
 *   node check-action-versions.mjs           # needs GITHUB_TOKEN + GITHUB_REPOSITORY
 *   node check-action-versions.mjs --dry-run # parse & print pins only (no network)
 */
import fs from 'node:fs';
import path from 'node:path';

const DRY = process.argv.includes('--dry-run');
const ROOT = path.resolve(process.cwd());
const WF_DIR = path.join(ROOT, '.github/workflows');

// ---- parse `uses: owner/repo@ref` pins from all workflow files ----
function collectPins() {
  const pins = new Map(); // "owner/repo" -> Set(refs)
  if (!fs.existsSync(WF_DIR)) return pins;
  for (const f of fs.readdirSync(WF_DIR)) {
    if (!/\.ya?ml$/.test(f)) continue;
    const text = fs.readFileSync(path.join(WF_DIR, f), 'utf8');
    const re = /uses:\s*([A-Za-z0-9._-]+\/[A-Za-z0-9._-]+)@([^\s#]+)/g;
    let m;
    while ((m = re.exec(text))) {
      const repo = m[1], ref = m[2];
      if (!pins.has(repo)) pins.set(repo, new Set());
      pins.get(repo).add(ref);
    }
  }
  return pins;
}

const pins = collectPins();
if (pins.size === 0) { console.log('no action pins found.'); process.exit(0); }

console.log('pinned actions:');
for (const [repo, refs] of pins) console.log('  ' + repo + ' @ ' + Array.from(refs).join(', '));

if (DRY) { console.log('\n--dry-run: parsed ' + pins.size + ' actions, no network calls.'); process.exit(0); }

const TOKEN = process.env.GITHUB_TOKEN;
const REPO = process.env.GITHUB_REPOSITORY; // owner/repo of THIS repo (for issue)
if (!TOKEN || !REPO) { console.error('GITHUB_TOKEN and GITHUB_REPOSITORY are required (or use --dry-run).'); process.exit(1); }

async function gh(url, opts = {}) {
  const res = await fetch('https://api.github.com' + url, {
    ...opts,
    headers: { 'Authorization': 'Bearer ' + TOKEN, 'Accept': 'application/vnd.github+json',
      'User-Agent': 'spab-deps-check', ...(opts.headers || {}) }
  });
  return res;
}

// major number from a ref like "v4", "v4.1.2", "4"
function major(ref) { const m = /v?(\d+)/.exec(ref); return m ? +m[1] : null; }

const behind = [];
for (const [repo, refs] of pins) {
  const res = await gh('/repos/' + repo + '/releases/latest');
  if (!res.ok) { console.log('  ? ' + repo + ': no latest release (status ' + res.status + ') — skipped'); continue; }
  const latest = (await res.json()).tag_name || '';
  const latestMajor = major(latest);
  for (const ref of refs) {
    const cur = major(ref);
    if (latestMajor != null && cur != null && latestMajor > cur) {
      behind.push({ repo, ref, latest });
      console.log('  ! ' + repo + '@' + ref + ' -> latest ' + latest);
    } else {
      console.log('  ok ' + repo + '@' + ref + ' (latest ' + latest + ')');
    }
  }
}

if (behind.length === 0) { console.log('\nAll pinned actions are current. No issue opened.'); process.exit(0); }

// ---- open or update a single tracking issue ----
const TITLE = 'Quarterly dependency review: action updates available';
const body = [
  'The quarterly check found newer major versions for pinned GitHub Actions:', '',
  ...behind.map(function (b) { return '- [ ] `' + b.repo + '@' + b.ref + '` → latest **' + b.latest + '**'; }),
  '', 'spab has zero package dependencies; these workflow action pins are the only',
  'thing that drifts. Review, bump, and close. (Generated by `deps-quarterly.yml`.)'
].join('\n');

const found = await (await gh('/repos/' + REPO + '/issues?state=open&labels=dependencies&per_page=100')).json();
const existing = Array.isArray(found) ? found.find(function (i) { return i.title === TITLE; }) : null;

if (existing) {
  await gh('/repos/' + REPO + '/issues/' + existing.number, { method: 'PATCH', body: JSON.stringify({ body }) });
  console.log('\nUpdated existing issue #' + existing.number + '.');
} else {
  const res = await gh('/repos/' + REPO + '/issues', { method: 'POST',
    body: JSON.stringify({ title: TITLE, body, labels: ['dependencies'] }) });
  const j = await res.json();
  console.log('\nOpened issue #' + (j.number || '?') + '.');
}
